import { 
  Bus, 
  User, 
  ShieldCheck, 
  Mail, 
  Lock, 
  Phone, 
  Eye, 
  EyeOff, 
  ArrowRight,
  CheckCircle2
} from 'lucide-react';

export default function AuthPage({ onLoginSuccess }) {
  // Role: 'user' or 'admin'
  const [role, setRole] = useState('user');
  
  // Auth Mode: Defaults to Sign Up first!
  const [isSignUp, setIsSignUp] = useState(true);

  // Form Fields
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    password: '',
    confirmPassword: '',
  });

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');

    // Sign Up Specific Validations
    if (isSignUp) {
      if (!formData.name || !formData.email || !formData.phone || !formData.password || !formData.confirmPassword) {
        setError('Please fill in all registration fields.');
        return;
      }
      if (formData.password !== formData.confirmPassword) {
        setError('Passwords do not match!');
        return;
      }
      if (formData.password.length < 6) {
        setError('Password must be at least 6 characters long.');
        return;
      }
    } else {
      // Sign In Validations
      if (!formData.email || !formData.password) {
        setError('Please provide both email and password.');
        return;
      }
    }

    const payload = {
      ...formData,
      role: role,
    };

    console.log(`Submitting ${isSignUp ? 'Sign Up' : 'Sign In'} for ${role}:`, payload);

    // Trigger parent callback upon success
    if (onLoginSuccess) {
      onLoginSuccess({ name: formData.name || 'User', email: formData.email, role: role });
    }
  };

  return (
    <div style={styles.pageContainer}>
      <div style={styles.authWrapper}>

        {/* LEFT COLUMN: Branding, Logo & Hero Info */}
        <div style={styles.leftSection}>
          <div style={styles.brandGroup}>
            <div style={styles.logoBadge}>
              <Bus size={32} color="#000000" />
            </div>
            <h1 style={styles.leftTitle}>EXPRESSBUS</h1>
          </div>

          <div style={styles.leftHeroContent}>
            <h2 style={styles.heroHeading}>
              Travel anywhere with total confidence.
            </h2>
            <p style={styles.heroSubtext}>
              Book real-time seats, manage your schedules, and get instant e-tickets on our secure digital platform.
            </p>

            <div style={styles.featureList}>
              <div style={styles.featureItem}>
                <CheckCircle2 size={18} color="#ffffff" />
                <span>Instant interactive seat selection</span>
              </div>
              <div style={styles.featureItem}>
                <CheckCircle2 size={18} color="#ffffff" />
                <span>Zero hassle digital refund & ticketing</span>
              </div>
              <div style={styles.featureItem}>
                <CheckCircle2 size={18} color="#ffffff" />
                <span>24/7 Priority customer support</span>
              </div>
            </div>
          </div>

          <div style={styles.leftFooter}>
            © {new Date().getFullYear()} ExpressBus Systems. All rights reserved.
          </div>
        </div>

        {/* RIGHT COLUMN: Sign In / Sign Up Form */}
        <div style={styles.rightSection}>
          
          {/* Passenger vs Admin Toggle */}
          <div style={styles.roleToggle}>
            <button
              type="button"
              onClick={() => { setRole('user'); setError(''); }}
              style={{
                ...styles.roleBtn,
                ...(role === 'user' ? styles.activeRole : {}),
              }}
            >
              <User size={16} /> Passenger
            </button>
            <button
              type="button"
              onClick={() => { setRole('admin'); setError(''); }}
              style={{
                ...styles.roleBtn,
                ...(role === 'admin' ? styles.activeRole : {}),
              }}
            >
              <ShieldCheck size={16} /> Admin
            </button>
          </div>

          {/* Title & Mode Toggle Prompt */}
          <div style={styles.formHeader}>
            <h2 style={styles.formTitle}>
              {isSignUp ? `Create ${role === 'admin' ? 'Admin' : 'Passenger'} Account` : `Sign In to ExpressBus`}
            </h2>
            <p style={styles.formSubtext}>
              {isSignUp ? 'Sign up once to unlock full online booking privileges.' : 'Welcome back! Please enter your details.'}
            </p>
          </div>

          {/* Error Message */}
          {error && <div style={styles.errorAlert}>{error}</div>}

          {/* Form Fields */}
          <form onSubmit={handleSubmit} style={styles.form}>
            
            {/* Full Name (Sign Up Only) */}
            {isSignUp && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Full Name</label>
                <div style={styles.inputWrapper}>
                  <User size={18} style={styles.inputIcon} />
                  <input
                    type="text"
                    name="name"
                    placeholder="John Doe"
                    value={formData.name}
                    onChange={handleInputChange}
                    style={styles.input}
                  />
                </div>
              </div>
            )}

            {/* Email Address */}
            <div style={styles.inputGroup}>
              <label style={styles.label}>Email Address</label>
              <div style={styles.inputWrapper}>
                <Mail size={18} style={styles.inputIcon} />
                <input
                  type="email"
                  name="email"
                  placeholder={role === 'admin' ? 'admin@expressbus.com' : 'passenger@mail.com'}
                  value={formData.email}
                  onChange={handleInputChange}
                  style={styles.input}
                />
              </div>
            </div>

            {/* Phone Number (Sign Up Only) */}
            {isSignUp && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Phone Number</label>
                <div style={styles.inputWrapper}>
                  <Phone size={18} style={styles.inputIcon} />
                  <input
                    type="tel"
                    name="phone"
                    placeholder="+1 (555) 000-0000"
                    value={formData.phone}
                    onChange={handleInputChange}
                    style={styles.input}
                  />
                </div>
              </div>
            )}

            {/* Password */}
            <div style={styles.inputGroup}>
              <label style={styles.label}>Password</label>
              <div style={styles.inputWrapper}>
                <Lock size={18} style={styles.inputIcon} />
                <input
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  placeholder="••••••••"
                  value={formData.password}
                  onChange={handleInputChange}
                  style={styles.input}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={styles.eyeBtn}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {/* Confirm Password (Sign Up Only) */}
            {isSignUp && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Confirm Password</label>
                <div style={styles.inputWrapper}>
                  <Lock size={18} style={styles.inputIcon} />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    name="confirmPassword"
                    placeholder="••••••••"
                    value={formData.confirmPassword}
                    onChange={handleInputChange}
                    style={styles.input}
                  />
                </div>
              </div>
            )}

            {/* Submit Button */}
            <button type="submit" style={styles.submitBtn}>
              <span>{isSignUp ? 'Create Account' : 'Sign In'}</span>
              <ArrowRight size={18} />
            </button>
          </form>

          {/* Switch between Sign In / Sign Up */}
          <div style={styles.switchContainer}>
            <span>
              {isSignUp ? 'Already registered?' : 'Need to register first?'}
            </span>
            <button
              type="button"
              onClick={() => {
                setIsSignUp(!isSignUp);
                setError('');
              }}
              style={styles.switchBtn}
            >
              {isSignUp ? 'Sign In' : 'Sign Up'}
            </button>
          </div>

        </div>

      </div>
    </div>
  );
}

